      ('starter-mantle-1952-card', 'hard', 'sports', 'How much did a 1952 Topps Mickey Mantle baseball card sell for at auction in 2022?', 'The SGC 9.5-graded card sold by Heritage Auctions in August 2022, final price.', '/items/baseball-card.svg', 'Illustration of a graded vintage baseball card in a clear case', 12600000.00, 'Final auction price', '2022-08-28', 'Heritage Auctions sold this 1952 Topps Mickey Mantle, graded SGC 9.5, for $12.6 million on August 28, 2022, a record for any sports card or memorabilia at the time.', 'Mickey Mantle 1952 Topps card, the ''finest known example'' of its kind, sells for record $12.6M', 'CBS Sports', 'https://www.cbssports.com/mlb/news/mickey-mantle-1952-topps-card-the-finest-known-example-of-its-kind-sells-for-record-12-6m/', 'sells for record $12.6M', ''),
      ('starter-ruby-slippers', 'hard', 'entertainment', 'How much did a pair of Dorothy''s ruby slippers from The Wizard of Oz sell for at auction?', 'The pair sold by Heritage Auctions on December 7, 2024, final price.', '/items/ruby-slippers.svg', 'Illustration of a pair of sparkly red heeled shoes with bows', 32500000.00, 'Final auction price', '2024-12-07', 'Heritage Auctions sold the ruby slippers Judy Garland wore in The Wizard of Oz for $32.5 million on December 7, 2024, the most ever paid for movie memorabilia at auction.', '''Wizard of Oz'' Ruby Slippers Sell for Record $32.5 Million', 'Antique Trader', 'https://www.antiquetrader.com/auctions/wizard-of-oz-ruby-slippers-sell-for-record-28-million', '$32.5 million ... by far, the most valuable movie memorabilia ever sold at auction', ''),
      ('starter-salvator-mundi', 'hard', 'luxury-goods', 'How much did Leonardo da Vinci''s painting Salvator Mundi sell for at auction?', 'Christie''s New York, November 15, 2017, final price including fees.', '/items/painting.svg', 'Illustration of a Renaissance portrait in an ornate gold frame', 450300000.00, 'Final auction price including the auction house''s fees', '2017-11-15', 'Salvator Mundi sold at Christie''s on November 15, 2017 for $450.3 million with fees (a $400 million hammer price), the most ever paid for a painting.', 'The Last Known Leonardo da Vinci Painting Just Sold', 'Artnet News', 'https://news.artnet.com/market/last-known-leonardo-da-vinci-painting-just-sold-1149032', 'With the auction house''s fees, the final price was $450.3 million.', ''),
      ('starter-sphere-las-vegas', 'hard', 'science-and-infrastructure', 'How much did the Sphere in Las Vegas cost to build?', 'The total construction cost of the venue, which opened in September 2023.', '/items/sphere-venue.svg', 'Illustration of a giant glowing sphere-shaped venue at night', 2300000000.00, 'Total construction cost', '2023-05-11', 'The Sphere''s construction cost grew to about $2.3 billion, making it the most expensive entertainment venue in Las Vegas. It opened on September 29, 2023.', 'Sphere (venue)', 'Wikipedia, citing the Las Vegas Review-Journal', 'https://en.wikipedia.org/wiki/Sphere_(venue)', 'final expected cost of $2.3 billion', ''),
      ('starter-james-webb-telescope', 'hard', 'science-and-infrastructure', 'How much did the James Webb Space Telescope cost NASA?', 'NASA''s total: building it (2003–2021) plus five years of operations, not adjusted for inflation.', '/items/space-telescope.svg', 'Illustration of a space telescope with gold hexagonal mirrors on a sunshield', 9700000000.00, 'NASA''s total development and five-year operations cost', '2021-12-25', 'NASA expects to spend $9.7 billion on Webb: $8.8 billion to build it and $861 million for five years of operations. Europe and Canada contributed separately.', 'How much does the James Webb Space Telescope cost?', 'The Planetary Society', 'https://www.planetary.org/articles/cost-of-the-jwst', '$9.7 billion over 24 years ... $8.8 billion for spacecraft development ... $861 million for five years of operations', '')
    ) as t(slug, difficulty, cat, prompt, context, image, image_alt, amount, definition, ref_date, explanation,
           src_title, src_publisher, src_url, src_excerpt, src_notes)
  loop
    insert into public.questions (slug, prompt, context, difficulty, category_id, image_url, image_alt, image_credit, status, is_sample)
    values (r.slug, r.prompt, r.context, r.difficulty, (select id from public.categories where slug = r.cat),
            r.image, r.image_alt, 'Illustration: Pricele', 'draft', false)
    on conflict (slug) do nothing
    returning id into v_qid;

    if v_qid is not null then
      insert into public.question_answers (question_id, answer_amount, answer_definition, reference_date, explanation)
